import{_ as o,o as e,c as a,ai as _}from"./chunks/framework.scx6l_IK.js";const i=JSON.parse('{"title":"金刚经16分-业障与清净心","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/金刚经16分-业障与清净心.md","filePath":"60-原文段落/金刚经16分-业障与清净心.md","lastUpdated":1778155802000}'),r={name:"60-原文段落/金刚经16分-业障与清净心.md"};function p(s,t,u,n,c,q){return e(),a("div",null,[...t[0]||(t[0]=[_('<h1 id="金刚经16分-业障与清净心" tabindex="-1">金刚经16分-业障与清净心 <a class="header-anchor" href="#金刚经16分-业障与清净心" aria-label="Permalink to &quot;金刚经16分-业障与清净心&quot;">​</a></h1><blockquote><p>来源：<a href="/01-Raw-Sources/16了空居士讲《金刚经》-第十六分能净业障分20161216">16了空居士讲《金刚经》-第十六分能净业障分20161216</a> 切分日期：2026-05-06</p></blockquote><hr><p><strong>以今世人轻贱故，先世罪业即为消灭，当得阿耨多罗三藐三菩提。</strong></p><p>若为人轻贱。若，如果。如果人家单独砍这几个字，&quot;为人轻贱&quot;，人家说，这个人地位很低，行为不怎么好。其实不是，是被人看不起。轻，就是轻视。贱，就是下贱，被人家看不起。</p><p>是人，这个受持读诵《金刚经》的人如果被人家看不起。先世罪业，应堕恶道，这个人过去生本来是有比较严重的业障，本来应堕恶道的。这句话其实不是说，他今生才来受持《金刚经》，严格来说，他过去生本来就已经受持。为什么我这么来推断啊？你们去看前边&quot;正信希有分&quot;等等，说听了《金刚经》能够一念生净信者，很不可思议了，更何况受持读诵，这就贯穿到前世，他不可能过去生造了很大的罪业，然后今生就突然间对《金刚经》生起那么大的信心，不可能的。如果前世罪业很大，本来前世就堕恶道了，哪有今生得人身的，是不是啊？</p><p>以今世人轻贱故，先世罪业即为消灭。其实被人家看不起，我们先世罪业就能够消灭。其实是人家看我们不起，我们不生嗔恚，你这个时候就是无我相无人相无众生相无寿者相，所以你这个时候业障也是虚妄的，因为你已经证得诸法空相了嘛。所以先世的罪业就会化解，是这个意思。</p><p>当得阿耨多罗三藐三菩提。如果他这辈子都是能够做到，人家看我不起，我也是无我无人无众生无寿者修一切善法，相信《金刚经》的经义，这就成就了阿耨多罗三藐三菩提。你们看&quot;行由品&quot;啊，六祖在那里破柴舂米，小沙弥诵着&quot;身是菩提树，心如明镜台，时时勤拂拭，莫使惹尘埃&quot;，六祖问他，&quot;上人诵的是什么偈啊？&quot;他说，&quot;尔这獦獠。&quot; 就是说，你这个獦獠。小沙弥都这么藐视他，但六祖就没有，说请上人带我去礼拜礼拜。人家对他那么轻贱，青少年出家人才叫沙弥，六祖当年是二十来岁了，已经是成年人了，人家还那么看他不起，&quot;尔这獦獠&quot;，六祖没有生气啊，他还说要去礼拜。从六祖身上就能看到他能够得成于忍，能够无我无人无众生无寿者修一切善法，破柴舂米就是善法，为寺庙出力嘛，所以他结果不是成就无上正等正觉吗？</p><p><strong>了即业障本来空，未了还需还宿债</strong></p><p>真正彻悟的人，业障对他已无实质影响，如同大海能容纳一切污浊而不被污染——不是现象消失，而是本质不受影响。但未悟的人，还是要老实面对因果。业障不是定业，是可以化解的。不信因果的人才是真正着相的人，他以为自己做坏事不用受报应，这才是执着。</p>',10)])])}const l=o(r,[["render",p]]);export{i as __pageData,l as default};
